INSERT INTO settings (key, value, updatedAt) VALUES ('aboutHeroTitle', 'حول TRQ', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutHeroDescription', 'We are a luxury interior design studio dedicated to creating timeless, sophisticated spaces that reflect our clients'' refined taste and elevated lifestyle.', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutHeroImage', '/uploads/14.webp', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutVisionTitle', 'رؤيتنا', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutVisionDescription', 'إعادة تعريف الحياة الفاخرة من خلال التصميم المدروس الذي يتجاوز الاتجاهات ويخلق جمالاً دائماً. نؤمن بمساحات تحكي القصص وتثير المشاعر وتصمد أمام اختبار الزمن.', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutMissionTitle', 'مهمتنا', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutMissionDescription', 'نخدم العملاء المميزين بتحويل مساحاتهم إلى ملاذات شخصية من الأناقة والوظيفة. من خلال الاهتمام الدقيق بالتفاصيل والشراكة التعاونية نقدم ديكورات داخلية تتجاوز التوقعات.', '2026-02-28 00:42:27');
