INSERT INTO settings (key, value, updatedAt) VALUES ('aboutApproach1Title', 'التوجيه المدروس', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutApproach1Description', 'Every design decision is purposeful, guided by deep understanding of our clients'' lifestyle and aesthetic preferences.', '2026-02-28 00:42:27');
