INSERT INTO settings (key, value, updatedAt) VALUES ('aboutApproach2Title', 'التميز المتعدد الطبقات', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutApproach2Description', 'نبني التعقيد من خلال الطبقات الحذرة للنسيج والمواد والعناصر التي تخلق العمق والاهتمام البصري.', '2026-02-28 00:42:27');
