INSERT INTO settings (key, value, updatedAt) VALUES ('aboutApproach3Title', 'الجودة الخالدة', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutApproach3Description', 'نعطي الأولوية للجمال الدائم على الاتجاهات العابرة واختيار المواد والتشطيبات التي تتقدم بأناقة.', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutApproach3Icon', 'Star', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutApproach4Title', 'الشراكة التعاونية', '2026-02-28 00:42:27');
