INSERT INTO settings (key, value, updatedAt) VALUES ('aboutHeroParagraph', 'Crafting exceptional spaces through vision, expertise, and dedication', '2026-02-28 00:42:30');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutWhoWeAreTitle', 'Who We Are', '2026-02-28 00:42:30');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutWhoWeAreParagraph1', 'TRQ is a luxury and creative interior design studio based in Riyadh, Saudi Arabia. Founded on the principles of excellence, innovation, and client-centric service, we have established ourselves as a premier design partner for discerning clients who demand the best.', '2026-02-28 00:42:30');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutWhoWeAreParagraph2', 'Our multidisciplinary team brings together expertise in interior design, architecture, furniture design, and project management to deliver comprehensive solutions that exceed expectations.', '2026-02-28 00:42:30');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutWhoWeAreParagraph3', 'Whether creating intimate residential spaces or grand commercial environments, we approach each project with the same level of dedication, creativity, and attention to detail that has become our hallmark.', '2026-02-28 00:42:30');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutWhoWeAreImage', 'https://images.unsplash.com/photo-1669387448840-610c588f003d?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&w=1080', '2026-02-28 00:42:30');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutVisionIcon', 'Eye', '2026-02-28 00:42:30');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutVisionParagraph', 'To be recognized as the leading luxury design studio in Saudi Arabia and beyond, setting new standards for creative excellence and transforming spaces into timeless works of art that inspire and elevate the human experience.', '2026-02-28 00:42:30');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutMissionIcon', 'Target', '2026-02-28 00:42:30');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutMissionParagraph', 'To deliver exceptional, bespoke design solutions that reflect our clients'' unique vision while exceeding their expectations. We are committed to combining artistic innovation with practical expertise, creating spaces that are both beautiful and functional.', '2026-02-28 00:42:30');
