INSERT INTO settings (key, value, updatedAt) VALUES ('workflowStep3Features', 'دمج ملاحظاتك وتحسين التصميم|إعداد الرسومات التقنية التفصيلية والمواصفات|إنهاء اختيارات المواد والأثاث|تأكيد الميزانية وإنشاء الجدول الزمني للمشروع|التنسيق مع المقاولين والموردين', '2026-02-28 01:10:48');
