INSERT INTO settings (key, value, updatedAt) VALUES ('workflowWhy3Description', 'سير عمل مبسط وإدارة مشاريع ذات خبرة والاهتمام بالتفاصيل يضمن إكمال المشاريع في الوقت المحدد وبأعلى المعايير', '2026-02-28 01:10:48');
