INSERT INTO settings (key, value, updatedAt) VALUES ('aboutCtaDescription_ar', 'دعنا نتعاون لإنشاء مساحة تعكس رؤيتك وتتجاوز توقعاتك.', '2026-02-28 01:10:51');
