INSERT INTO settings (key, value, updatedAt) VALUES ('servicesHeroParagraph_ar', 'مجموعة شاملة من الخدمات التصميمية المتخصصة', '2026-02-28 01:10:51');
INSERT INTO settings (key, value, updatedAt) VALUES ('servicesTitle_ar', 'حلول تصميم كاملة', '2026-02-28 01:10:51');
INSERT INTO settings (key, value, updatedAt) VALUES ('servicesDescription_ar', 'من المساحات السكنية الحميمة إلى المشاريع التجارية الكبرى، من أجنحة المعارض إلى الأثاث المخصص، يقدم TRQ مجموعة شاملة من خدمات التصميم. يضمن نهجنا متعدد التخصصات التكامل السلس عبر جميع جوانب مشروعك، مما يوفر نتائج متماسكة واستثنائية.', '2026-02-28 01:10:51');
INSERT INTO settings (key, value, updatedAt) VALUES ('servicesHighlightsTitle_ar', 'مميزات الخدمة', '2026-02-28 01:10:51');
